#!/usr/bin/env node
// Generates TypeScript types from protocol/schema/protocol.v1.json.
// Zero dependencies: supports exactly the JSON Schema subset the protocol uses
// ($ref, const, enum, oneOf, object/array/string/integer/number/boolean).
//
//   node protocol/scripts/gen-ts.mjs          # write protocol/generated/protocol.ts
//   node protocol/scripts/gen-ts.mjs --check  # exit 1 if the generated file is stale

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const schemaPath = join(here, "..", "schema", "protocol.v1.json");
const outPath = join(here, "..", "generated", "protocol.ts");
const schema = JSON.parse(readFileSync(schemaPath, "utf8"));

function refName(ref) {
  const m = /^#\/\$defs\/(.+)$/.exec(ref);
  if (!m) throw new Error(`Unsupported $ref: ${ref}`);
  return m[1];
}

function doc(text, indent = "") {
  if (!text) return "";
  return `${indent}/** ${text.replace(/\*\//g, "*\\/")} */\n`;
}

function tsType(s, indent = "") {
  if (s.$ref) return refName(s.$ref);
  if ("const" in s) return JSON.stringify(s.const);
  if (s.enum) return s.enum.map((v) => JSON.stringify(v)).join(" | ");
  if (s.oneOf) return s.oneOf.map((x) => tsType(x, indent)).join("\n" + indent + "  | ");
  switch (s.type) {
    case "string":
      return "string";
    case "integer":
    case "number":
      return "number";
    case "boolean":
      return "boolean";
    case "array":
      return `${wrap(tsType(s.items ?? {}, indent))}[]`;
    case "object": {
      const props = s.properties ?? {};
      const req = new Set(s.required ?? []);
      const keys = Object.keys(props);
      if (keys.length === 0) {
        return s.additionalProperties === false ? "Record<string, never>" : "Record<string, unknown>";
      }
      const inner = indent + "  ";
      const lines = keys.map((k) => {
        const p = props[k];
        return `${doc(p.description, inner)}${inner}${k}${req.has(k) ? "" : "?"}: ${tsType(p, inner)};`;
      });
      if (s.additionalProperties && s.additionalProperties !== false) {
        lines.push(`${inner}[key: string]: unknown;`);
      }
      return `{\n${lines.join("\n")}\n${indent}}`;
    }
    default:
      return "unknown";
  }
}

function wrap(t) {
  return /[|&\s]/.test(t) && !t.startsWith("{") ? `(${t})` : t;
}

const out = [];
out.push("// AUTO-GENERATED by protocol/scripts/gen-ts.mjs from protocol/schema/protocol.v1.json.");
out.push("// Do not edit by hand. Run `npm run gen` in /server (or the script directly).");
out.push("");
out.push(`export const PROTOCOL_VERSION = ${schema["x-protocol-version"]} as const;`);
out.push("");

const defs = schema.$defs;
for (const [name, def] of Object.entries(defs)) {
  out.push(doc(def.description) + `export type ${name} = ${tsType(def)};`);
  out.push("");
}

// Discriminator helpers.
for (const unionName of ["ClientMessage", "ServerMessage", "SessionEvent"]) {
  const members = defs[unionName].oneOf.map((m) => defs[refName(m.$ref)].properties.type.const);
  const constName = unionName.replace(/([a-z])([A-Z])/g, "$1_$2").toUpperCase() + "_TYPES";
  out.push(`export const ${constName} = ${JSON.stringify(members)} as const;`);
  out.push("");
}

const text = out.join("\n");

if (process.argv.includes("--check")) {
  const current = existsSync(outPath) ? readFileSync(outPath, "utf8") : "";
  if (current !== text) {
    console.error("protocol/generated/protocol.ts is stale. Run the generator.");
    process.exit(1);
  }
  console.log("protocol types up to date");
} else {
  writeFileSync(outPath, text);
  console.log(`wrote ${outPath}`);
}
